using TravelAgentRAG.Models;

namespace TravelAgentRAG.Data;

/// <summary>
/// Static, hardcoded travel knowledge base — Indian cities edition.
/// In a real app, this would come from a database or API.
/// This is the "source of truth" that the RAG pipeline retrieves from.
/// </summary>
public static class TravelDataStore
{
    public static List<TravelDestination> GetDestinations() =>
    [
        new TravelDestination
        {
            Name = "Jaipur",
            Country = "India",
            Description = "Jaipur, known as the Pink City, is the capital of Rajasthan and a vibrant showcase of Indian royal heritage. The city gets its nickname from the terracotta pink color of its old city buildings, painted in 1876 to welcome Prince Albert. Part of India's famous Golden Triangle tourist circuit along with Delhi and Agra, Jaipur offers magnificent forts, palaces, and colorful bazaars. The city beautifully blends Rajput architecture with a modern vibe.",
            BestTimeToVisit = "The best time to visit Jaipur is from October to March when the weather is cool and pleasant (15-25°C). Winters (December-February) are ideal with clear blue skies perfect for sightseeing. Avoid April to June when temperatures soar above 45°C and the heat is unbearable. The monsoon season (July-September) brings some relief from heat but can cause waterlogging and disrupt sightseeing plans.",
            TopAttractions = "Amber Fort (with its stunning Sheesh Mahal — Mirror Palace), Hawa Mahal (Palace of Winds — Jaipur's most photographed landmark), City Palace (still partially a royal residence), Jantar Mantar (UNESCO World Heritage astronomical observation site), Nahargarh Fort (best sunset views of the city), Jal Mahal (Water Palace floating on Man Sagar Lake), Albert Hall Museum, Birla Mandir, and the colorful bazaars of Johari Bazaar (jewelry), Bapu Bazaar (textiles & mojari shoes), and Tripolia Bazaar (lacquer bangles).",
            AverageBudgetPerDay = "Jaipur is very affordable. Budget travelers can manage on 1,500-2,500 INR (18-30 USD) per day including hostel stays, street food, and local transport. Mid-range travelers spending 4,000-6,000 INR (50-75 USD) per day can enjoy heritage haveli hotels, good restaurants, and all attractions comfortably. Luxury heritage palace hotels like Rambagh Palace and Samode Haveli offer royal experiences at 15,000-30,000 INR per night. Auto-rickshaw rides within the city cost 50-200 INR.",
            LocalCuisine = "Dal Baati Churma (Rajasthan's signature dish — baked wheat balls with rich lentil curry and sweet churma), Laal Maas (fiery red meat curry made with mathania chillies), Pyaaz Kachori (crispy onion-stuffed fried pastry — best at Rawat Mishthan Bhandar), Ghewar (honeycomb-shaped sweet soaked in sugar syrup — a monsoon specialty), Lassi from the iconic Lassiwala on MI Road (serving since 1944), Rajasthani Thali at Chokhi Dhani for a full village-style meal experience, Kulfi Faluda, Mirchi Vada, and Mawa Kachori from Samrat Restaurant.",
            TravelTips = "Hire a local guide for Amber Fort — the history and hidden stories are fascinating and worth every rupee. Bargain hard at bazaars — start at 40-50% of the asking price, it's expected. Auto-rickshaws should use meters but rarely do — agree on price before riding or use Ola/Uber. Visit forts early morning (8-9 AM) to beat the heat and crowds. Dress modestly when visiting temples. The Jaipur Literature Festival in January is world-famous and free to attend. Buy a composite ticket (valid 2 days) for Amber Fort, Hawa Mahal, Jantar Mantar, Nahargarh Fort, and Albert Hall Museum — saves significant money."
        },

        new TravelDestination
        {
            Name = "Goa",
            Country = "India",
            Description = "Goa is India's smallest state and its most famous beach destination, located on the western coast along the Arabian Sea. A former Portuguese colony for over 450 years, Goa has a unique blend of Indian and Portuguese cultures visible in its churches, cuisine, and architecture. It offers everything from lively beach parties and water sports to quiet villages, spice plantations, and UNESCO World Heritage churches. North Goa is known for its vibrant nightlife and tourist beaches, while South Goa offers quieter, more pristine beaches and luxury resorts.",
            BestTimeToVisit = "The best time to visit Goa is from November to February when the weather is perfect — sunny skies, low humidity, and temperatures around 25-32°C. This is peak tourist season with Christmas and New Year being the busiest (and most expensive) period. October and March are good shoulder months with fewer crowds. Avoid June to September — the monsoon brings heavy rains, rough seas (beaches are unsafe for swimming), and many shacks and restaurants shut down. However, monsoon Goa has a unique lush green beauty and is very budget-friendly.",
            TopAttractions = "Basilica of Bom Jesus (UNESCO World Heritage — holds St. Francis Xavier's remains), Fort Aguada, Dudhsagar Waterfalls (spectacular four-tiered waterfall on the Goa-Karnataka border), Anjuna Flea Market (Wednesday) and Saturday Night Market in Arpora, Baga Beach and Calangute Beach for water sports, Palolem Beach in South Goa for a quieter experience, Se Cathedral, Old Goa churches, Chapora Fort (famous from Dil Chahta Hai), spice plantations in Ponda, dolphin spotting boat trips, and the vibrant Fontainhas Latin Quarter in Panaji.",
            AverageBudgetPerDay = "Goa is moderately priced and varies hugely by season. Budget travelers can manage on 1,500-3,000 INR (18-35 USD) per day in non-peak season with guesthouses and beach shack meals. Mid-range travelers should expect 4,000-8,000 INR (50-100 USD) per day for comfortable hotels and restaurant dining. Prices double during Christmas-New Year week. Renting a scooter (300-500 INR/day) is the cheapest and most fun way to get around. Beer is cheap — 60-100 INR for a pint at beach shacks.",
            LocalCuisine = "Fish Curry Rice (the staple Goan meal — spicy coconut-based curry with fresh fish), Prawn Balchão (tangy, spicy prawn pickle-curry — Portuguese-influenced), Pork Vindaloo (NOT the British version — the authentic Goan one is tangy with toddy vinegar and spices), Bebinca (a traditional 7-layer Goan dessert), Chicken Cafreal (green masala grilled chicken), Goan Sausage Chilly Fry, fresh seafood at any beach shack (kingfish, pomfret, tiger prawns), Feni (local cashew or coconut spirit), and Poi (traditional Goan bread). Don't miss the fish thali at a local 'bhatti' (tavern).",
            TravelTips = "Rent a scooter or Activa for maximum flexibility — it's the Goan way of getting around (200-500 INR/day, international driving permit technically required). Carry cash — many beach shacks and smaller places don't accept cards. Don't swim at beaches with red flags — the currents are dangerous. Sunscreen is essential year-round. North Goa is for parties and socializing, South Goa for relaxation and couples. Negotiate prices for water sports — touts often quote inflated rates. Visit Old Goa churches early morning for a peaceful experience. Try the local feni but go easy — it's potent."
        },

        new TravelDestination
        {
            Name = "Manali",
            Country = "India",
            Description = "Manali is a popular hill station nestled in the mountains of Himachal Pradesh at an altitude of 2,050 meters in the Kullu Valley. Surrounded by snow-capped peaks, dense deodar forests, and the roaring Beas River, Manali is a gateway to adventure sports and the high-altitude deserts of Ladakh via the Atal Tunnel and Rohtang Pass. The town blends hippie backpacker culture with traditional Himachali village life, making it a favorite for honeymooners, trekkers, and families alike.",
            BestTimeToVisit = "Manali is a year-round destination with different charms each season. Summer (April-June) is peak season with pleasant weather (10-25°C), ideal for sightseeing and adventure sports. Winter (December-February) brings heavy snowfall — perfect for snow activities at Solang Valley and Rohtang. Autumn (September-November) offers clear skies and stunning fall colors. Monsoon (July-August) brings heavy rains and landslides that can block roads — avoid unless you enjoy dramatic landscapes. For snow, visit in January-February.",
            TopAttractions = "Rohtang Pass (snow-covered mountain pass at 3,978m — now accessible via the 9.02 km Atal Tunnel), Solang Valley (skiing, paragliding, zorbing), Hadimba Temple (ancient wooden temple in a cedar forest), Old Manali (cafes, shops, backpacker vibe), Jogini Waterfall (short trek from Vashisht), Vashisht Hot Springs and Temple, Mall Road for shopping and strolling, Beas River rafting, Hampta Pass trek, Great Himalayan National Park (UNESCO World Heritage), and the scenic drive to Sissu and Lahaul Valley through Atal Tunnel.",
            AverageBudgetPerDay = "Budget travelers can manage on 1,500-2,500 INR (18-30 USD) per day with guesthouses in Old Manali and dhaba meals. Mid-range travelers spending 4,000-7,000 INR (50-85 USD) per day get comfortable hotels with valley views. Luxury cottages and resorts run 10,000-20,000 INR per night. Paragliding costs 2,500-3,500 INR, river rafting 500-1,500 INR depending on stretch. Rohtang Pass permits cost around 550 INR per person. Off-season (monsoon) prices drop 40-50%.",
            LocalCuisine = "Siddu (steamed wheat bread stuffed with poppy seeds or walnuts — a Himachali specialty), Thukpa (Tibetan noodle soup — perfect for cold evenings), Momos (steamed or fried dumplings available everywhere), Dham (traditional Himachali feast served on special occasions — rice, dal, rajma, curd), fresh trout from the Beas River (grilled or fried — must try), Babru (stuffed fried bread), Kullu Trout, Apple dishes and fresh apple cider, Tibetan bread and butter tea in Old Manali cafes, and the famous Maggi and chai at every mountain viewpoint.",
            TravelTips = "Book Rohtang Pass or Atal Tunnel permits online in advance at the Manali administration website — they have daily visitor limits. Carry warm clothes even in summer — evenings get chilly at this altitude. Acute Mountain Sickness can affect some people — acclimatize for a day before heading to higher passes. The Manali-Leh Highway is one of the world's most spectacular drives — open only June to October. Old Manali has better cafes and vibe than Mall Road. Carry cash — ATMs are unreliable in remote areas. Hire local taxi for Solang/Rohtang — roads are not suitable for self-driving."
        },

        new TravelDestination
        {
            Name = "Varanasi",
            Country = "India",
            Description = "Varanasi (also called Banaras or Kashi) is one of the world's oldest continuously inhabited cities, situated on the banks of the sacred Ganges River in Uttar Pradesh. It is the spiritual capital of India and the holiest city for Hindus, who believe that dying here grants moksha (liberation from the cycle of rebirth). The city is a mesmerizing labyrinth of ancient ghats (stepped riverbanks), narrow lanes, over 2,000 temples, and an unbroken chain of rituals that have continued for over 3,000 years.",
            BestTimeToVisit = "The best time to visit Varanasi is from October to March when the weather is pleasant (10-25°C). November to February is ideal — cool mornings make the sunrise boat ride magical. The city is especially vibrant during Dev Deepawali (October/November) when a million diyas (oil lamps) light up the ghats, and during Maha Shivaratri. Avoid April to June — temperatures exceed 45°C. Monsoon (July-September) brings flooding of the ghats and oppressive humidity.",
            TopAttractions = "Dashashwamedh Ghat (the main ghat — don't miss the grand Ganga Aarti ceremony every evening at 6:45 PM), Manikarnika Ghat (the sacred burning ghat — observe respectfully), Kashi Vishwanath Temple (one of the 12 Jyotirlingas — newly renovated Kashi Vishwanath Corridor), sunrise boat ride on the Ganges (an unmissable experience), Assi Ghat, Sarnath (where Buddha gave his first sermon — 10 km away), Ramnagar Fort across the river, the narrow lanes (galis) of the old city, silk weaving workshops (Banarasi silk is world-famous), and BHU campus with Bharat Kala Bhavan museum.",
            AverageBudgetPerDay = "Varanasi is extremely affordable. Budget travelers can manage on 1,000-2,000 INR (12-25 USD) per day with guesthouse stays near the ghats and street food. Mid-range travelers spending 3,000-5,000 INR (35-60 USD) per day can enjoy heritage guesthouses with Ganges views and good restaurants. A sunrise boat ride costs 150-300 INR per person (shared) or 500-800 INR for a private boat. Authentic Banarasi silk sarees range from 2,000 to 50,000+ INR depending on the weave.",
            LocalCuisine = "Kachori Sabzi (crispy fried pastry with spicy potato curry — the quintessential Banarasi breakfast from Kachori Gali), Banarasi Paan (betel leaf with sweet fillings — an iconic after-meal treat), Tamatar Chaat (tangy tomato chaat unique to Varanasi), Lassi from Blue Lassi Shop (legendary lassi shop near Manikarnika — thick, creamy, with seasonal fruits), Thandai (spiced cold milk, sometimes with bhang during Holi), Banarasi Chaat, Malaiyo (a winter-only frothy milk dessert available November-February), Litti Choki, and sweets from Ram Bhandar.",
            TravelTips = "Hire a local guide for your first day — the narrow lanes are a labyrinth and you WILL get lost. Reach Dashashwamedh Ghat by 6 PM to get a good spot for the Ganga Aarti — it gets extremely crowded. Take the sunrise boat ride between 5:30-6:30 AM. Be respectful at Manikarnika Ghat — no photography is allowed. Wear shoes you can slip on and off easily (you'll be entering many temples). Beware of scams — fake pundits (priests) at the ghats will ask for donations. The city is vegetarian-friendly but finding non-veg food is harder near the ghats. Cycle rickshaws are the best way to navigate the old city."
        },

        new TravelDestination
        {
            Name = "Munnar",
            Country = "India",
            Description = "Munnar is a breathtaking hill station in the Western Ghats of Kerala at an altitude of 1,532 meters, famous for its rolling hills carpeted with endless tea plantations. Once the summer retreat of the British colonial government, Munnar today is a paradise for nature lovers. The landscape is dominated by lush green tea estates, misty mountains, pristine streams, and protected wildlife sanctuaries home to the endangered Nilgiri Tahr. Munnar is part of Kerala, 'God's Own Country,' and offers a cooler escape from the tropical coast.",
            BestTimeToVisit = "The best time to visit Munnar is from September to May. September to November offers post-monsoon lush greenery with clear skies. December to February is cool and misty (5-15°C) — carry warm clothes. March to May is warmer but comfortable. The Neelakurinji flowers bloom once every 12 years (next bloom expected around 2030) and carpet the hills in purple-blue — a once-in-a-lifetime sight. June to August brings heavy monsoon rains — roads can be treacherous but the waterfalls are at their most spectacular.",
            TopAttractions = "Tea Museum (learn about tea production and taste fresh tea), Eravikulam National Park (home to the endangered Nilgiri Tahr mountain goat), Top Station (highest point in Munnar with panoramic views of Tamil Nadu), Mattupetty Dam and Lake (boating with mountain backdrop), Echo Point, Attukal Waterfalls, Lakkam Waterfalls, Kundala Lake (shikara boat rides), Tata Tea plantations walk, Anamudi Peak (South India's highest peak at 2,695m — trekking with permits), and the scenic drive through the winding roads surrounded by tea gardens.",
            AverageBudgetPerDay = "Munnar is moderately priced. Budget travelers can manage on 1,500-2,500 INR (18-30 USD) per day with homestays and local meals. Mid-range travelers spending 4,000-6,000 INR (50-75 USD) per day can enjoy tea estate resorts and Kerala cuisine. Luxury resorts and treehouse stays run 8,000-20,000 INR per night. Jeep safari to Top Station costs around 2,000-3,000 INR. Buying fresh tea directly from estates is very affordable — 200-500 INR per kg for premium varieties.",
            LocalCuisine = "Kerala Sadya (traditional vegetarian feast served on banana leaf — best during Onam festival), Kerala Fish Curry (tangy, spicy curry made with kokum and coconut), Appam with Stew (lacy rice pancakes with coconut milk vegetable or chicken stew), Kerala Parotta with Beef Fry (a local favorite), Puttu and Kadala Curry (steamed rice cake with black chickpea curry — classic breakfast), Munnar tea and fresh cardamom tea from plantations, Kerala Banana Chips, Payasam (sweet pudding made with rice/vermicelli), and fresh spices — cardamom, pepper, and cinnamon bought directly from spice gardens.",
            TravelTips = "The road from Kochi to Munnar (130 km) is winding with 40+ hairpin bends — carry motion sickness medication if prone. Hire a local jeep or car with driver for sightseeing — the mountain roads are not for novice drivers. Book Eravikulam National Park tickets online — walk-in queues can be 2+ hours during peak season. Carry a light jacket even in summer — mornings and evenings are chilly. The best tea to buy is 'special grade' orange pekoe from Kanan Devan Hills Plantations. Leeches are common on forest trails during/after monsoon — wear full shoes and carry salt or lemon. Don't miss watching sunrise from Top Station."
        },

        new TravelDestination
        {
            Name = "Udaipur",
            Country = "India",
            Description = "Udaipur, known as the City of Lakes and the Venice of the East, is a romantic city in southern Rajasthan built around a series of artificial lakes. Founded in 1559 by Maharana Udai Singh II, the city is famous for its stunning lake palaces, grand courtyards, and beautiful gardens. The Lake Palace (now a luxury hotel) floating on Lake Pichola is one of India's most iconic images. Udaipur has served as a filming location for James Bond (Octopussy) and many Bollywood movies. The city has a more relaxed, artistic vibe compared to Jaipur.",
            BestTimeToVisit = "The best time to visit Udaipur is from September to March. October to February is ideal — pleasant weather (12-28°C), clear skies, and the lakes are full after the monsoon. The city is magical during Diwali and the Mewar Festival (March/April). Avoid April to June when temperatures exceed 40°C. The monsoon (July-August) fills up the lakes beautifully and the surrounding Aravalli hills turn lush green, but heavy rains can disrupt some outdoor plans.",
            TopAttractions = "City Palace (the largest palace complex in Rajasthan — stunning lakeside architecture), Lake Pichola boat ride at sunset (a must-do), Jag Mandir island palace, Jagdish Temple (Indo-Aryan architecture masterpiece), Saheliyon-ki-Bari (Garden of the Maidens), Monsoon Palace (Sajjangarh — hilltop palace with panoramic views), Bagore ki Haveli (evening Dharohar folk dance show — don't miss it), Fateh Sagar Lake, Shilpgram crafts village, Vintage Car Museum, and the narrow streets of the old city with art galleries, miniature painting studios, and rooftop cafes overlooking the lake.",
            AverageBudgetPerDay = "Udaipur is affordable with options for every budget. Budget travelers can manage on 1,500-2,500 INR (18-30 USD) per day with guesthouse stays and local food. Mid-range travelers spending 4,000-7,000 INR (50-85 USD) per day can enjoy lakeside haveli hotels and rooftop dining. The famous Taj Lake Palace hotel starts at 35,000+ INR per night for the ultimate luxury. Lake Pichola boat ride costs 400-800 INR. City Palace entry is 300 INR for Indians and 250 INR for audio guide.",
            LocalCuisine = "Dal Baati Churma (Rajasthani staple — available everywhere), Gatte ki Sabzi (gram flour dumplings in spicy yogurt curry — a Udaipur specialty), Ker Sangri (desert beans and berries — unique to Rajasthan), Doodh Jalebi (jalebi soaked in warm milk — a Udaipur breakfast tradition), Kachori at Sukhadia Circle, Laal Maas (fiery mutton curry), rooftop dinner at Ambrai or Upré overlooking Lake Pichola and City Palace (one of India's most romantic dining experiences), Paneer specialties, and lassi. Try a traditional Rajasthani thali at Natraj or Shreenath dining halls.",
            TravelTips = "Book a Lake Pichola sunset boat ride a day in advance during peak season. The Dharohar folk dance show at Bagore ki Haveli (7 PM daily) is a must — reach by 6:30 PM for good seats (150 INR). Stay near Lal Ghat or Gangaur Ghat for the best lake views on a budget. Udaipur is a great city for walking — most attractions in the old city are close together. Visit City Palace early morning (9:30 AM opening) for fewer crowds. The city is a hub for miniature painting — take a workshop at one of the art schools. Use Ola/Uber or rent a scooter (250-400 INR/day) to visit Sajjangarh and Fateh Sagar. Udaipur is well connected to Jaipur, Jodhpur, and Mount Abu for a Rajasthan circuit."
        },

        new TravelDestination
        {
            Name = "Rishikesh",
            Country = "India",
            Description = "Rishikesh is a holy city on the banks of the Ganges in the foothills of the Himalayas in Uttarakhand. Known as the Yoga Capital of the World, it gained international fame when The Beatles visited Maharishi Mahesh Yogi's ashram here in 1968. Today, Rishikesh is a unique blend of spirituality and adventure — you can attend a yoga class in the morning and go white-water rafting in the afternoon. The city is also the gateway to the Char Dham pilgrimage and several Himalayan treks.",
            BestTimeToVisit = "The best time to visit Rishikesh is from September to November and February to May. September-November offers pleasant weather (20-30°C) and the river is perfect for rafting after the monsoon. February-May is ideal for yoga retreats and outdoor activities. Avoid July-August — heavy monsoons cause flooding, landslides, and rafting is suspended. Winters (December-January) are cold (5-15°C) but peaceful — great for yoga and meditation retreats with fewer tourists.",
            TopAttractions = "Lakshman Jhula and Ram Jhula (iconic suspension bridges over the Ganges), Beatles Ashram / Maharishi Mahesh Yogi Ashram (now a beautiful ruin with street art), Triveni Ghat (evening Ganga Aarti), white-water rafting on the Ganges (16 km and 26 km stretches with Grade 3-4 rapids), bungee jumping at Jumpin Heights (India's highest at 83 meters), cliff jumping, Neer Garh Waterfall, yoga and meditation classes at Parmarth Niketan or Sivananda Ashram, camping on Ganges beaches, Rajaji National Park (tiger reserve), and the scenic trek to Kunjapuri Temple for sunrise views.",
            AverageBudgetPerDay = "Rishikesh is very budget-friendly. Budget travelers and backpackers can manage on 1,000-2,000 INR (12-25 USD) per day with ashram stays (500-1,000 INR including meals) and street food. Mid-range travelers spending 3,000-5,000 INR (35-60 USD) per day get riverside camps or boutique hotels. White-water rafting costs 1,000-2,500 INR depending on the stretch. Bungee jumping is 3,550 INR. Yoga courses range from 500 INR per drop-in class to 20,000-50,000 INR for multi-week teacher training programs.",
            LocalCuisine = "Rishikesh is a strictly VEGETARIAN city (no meat, fish, or eggs sold anywhere — it's a holy city). Popular dishes include: Aloo Puri (fried bread with spiced potato — classic breakfast), Chole Bhature (spiced chickpeas with fried bread), fresh fruit smoothie bowls and acai bowls at the many health-food cafes in Tapovan, Israeli and Continental food at backpacker cafes near Lakshman Jhula, Thali meals at ashrams (simple, sattvic, and incredibly cheap), Garhwali Dal with steamed rice, Maggi at every chai stall, and fresh juice. The German Bakery and Little Buddha Cafe are traveler favorites.",
            TravelTips = "The city is divided into three areas: Rishikesh town (the main city — less touristy), Swarg Ashram (temples, ashrams, Ganga Aarti), and Tapovan/Lakshman Jhula (backpacker central with cafes, yoga studios, adventure sports). Stay in Tapovan for the best experience. Book rafting through your hotel or a registered operator — avoid touts who offer cheap uninsured trips. No alcohol is sold in Rishikesh (it's a dry holy city). Carry cash — many small shops don't accept UPI or cards. Respect the ashram culture — dress modestly. The 13 km and 26 km rafting stretches end at different points — clarify the route beforehand."
        },

        new TravelDestination
        {
            Name = "Darjeeling",
            Country = "India",
            Description = "Darjeeling is a charming hill town in West Bengal perched at 2,042 meters in the Lesser Himalayas, famous worldwide for its tea — Darjeeling tea is often called the 'Champagne of Teas.' Established as a British hill station in the mid-1800s, the town retains its colonial character with Gothic churches, heritage hotels, and the iconic toy train. On clear days, you can see the majestic Kanchenjunga — the world's third-highest peak — dominating the horizon. The town has a unique cultural mix of Nepali, Tibetan, and Bengali influences.",
            BestTimeToVisit = "The best time to visit Darjeeling is from October to December and March to May. October-November offers crystal-clear views of Kanchenjunga with post-monsoon skies and pleasant weather (5-15°C). March-May is spring with rhododendrons in bloom and comfortable temperatures. Winters (December-February) are cold (0-7°C) but offer a cozy, less crowded experience — snowfall is rare but possible. Avoid June to September — the monsoon brings heavy rains, frequent landslides, and obscured mountain views.",
            TopAttractions = "Tiger Hill sunrise point (watch dawn break over Kanchenjunga and sometimes Everest — reach by 4 AM), Darjeeling Himalayan Railway toy train (UNESCO World Heritage — ride the Ghum-Darjeeling stretch), Batasia Loop (spiral railway with war memorial), Happy Valley Tea Estate (tour the factory and taste fresh tea), Padmaja Naidu Himalayan Zoological Park (home to red pandas and snow leopards), Himalayan Mountaineering Institute, Peace Pagoda (Japanese Buddhist temple), Observatory Hill, Rock Garden and Ganga Maya Park, Nightingale Park, and a day trip to Sandakphu (highest point in West Bengal with views of four of the five highest peaks in the world).",
            AverageBudgetPerDay = "Darjeeling is moderately affordable. Budget travelers can manage on 1,500-2,500 INR (18-30 USD) per day with budget hotels and local eateries. Mid-range travelers spending 3,500-6,000 INR (42-72 USD) per day can enjoy heritage hotels and good restaurants. Luxury stays at heritage properties like Mayfair or Windamere Hotel cost 8,000-15,000 INR per night. Toy train joy ride costs 100-1,500 INR depending on class and route. Shared jeep to Tiger Hill costs 300-400 INR (leaves at 4 AM).",
            LocalCuisine = "Darjeeling tea — taste it fresh at any tea estate or at Nathmull's tea shop (the most famous tea seller, operating since 1931). Momos (steamed or fried — Darjeeling arguably has the best momos in India), Thukpa (hearty Tibetan noodle soup perfect for cold evenings), Churpee (hardened yak cheese — a local snack), Sel Roti (sweet ring-shaped rice bread — a Nepali specialty), Wai Wai sadeko (spicy instant noodle salad — a local street food obsession), Tongba (fermented millet drink — warm and mildly alcoholic), Shaphaley (Tibetan meat-stuffed bread), and Nepali-style dal bhat. Glenary's Bakery on the Mall is a heritage institution for cakes and breakfast.",
            TravelTips = "Reach Tiger Hill by 4:00-4:30 AM for sunrise — book a shared jeep the evening before from the taxi stand at Chowrasta. Carry warm layers year-round — mornings and evenings are cold even in spring. The toy train is more about the experience than speed — the Ghum-Darjeeling 45-min joy ride is the best stretch. Darjeeling is best explored on foot — wear comfortable walking shoes as the town is built on steep slopes. Buy authentic Darjeeling tea only from established shops (Nathmull's, Golden Tips) — much 'Darjeeling tea' sold to tourists is fake. New Jalpaiguri (NJP) is the nearest major railway station — shared jeeps take 3-3.5 hours to reach Darjeeling. The Mall Road (Chowrasta) is the heart of town — great for evening walks with mountain views."
        },

        new TravelDestination
        {
            Name = "Kolkata",
            Country = "India",
            Description = "Kolkata (formerly Calcutta), the City of Joy and the cultural capital of India, is situated along the banks of the Hooghly River in West Bengal. As the former capital of British India until 1911, Kolkata boasts grand colonial architecture, historic tramways, iconic bridges, vibrant literary and intellectual culture, and a legendary culinary scene. It is world-renowned for its grand Durga Puja celebrations, adda (intellectual chats) at historic coffee houses, and rich heritage of Nobel laureates, poets, and artists.",
            BestTimeToVisit = "The best time to visit Kolkata is from October to March when the weather is cool, pleasant, and dry (15-28°C). October is especially magical during Durga Puja (UNESCO Intangible Cultural Heritage), when the entire city transforms into a massive open-air art carnival with thousands of themed pandals and dazzling lights. Winters (December-February) are ideal for heritage walks, river cruises, and book fairs. Avoid April to June when extreme heat and humidity prevail (temperatures reach 40°C+). The monsoon (July-September) brings heavy rains and waterlogged streets.",
            TopAttractions = "Victoria Memorial (grand white marble monument set in 64 acres of gardens), Howrah Bridge (cantilever bridge over the Hooghly River — iconic symbol of Kolkata), Dakshineswar Kali Temple and Belur Math (across the river, spiritual epicenter of Ramakrishna and Swami Vivekananda), Indian Museum (oldest and largest museum in India), Park Street (historic dining and nightlife hub), College Street (Boipara — world's largest second-hand book market) and Indian Coffee House, Kumartuli (potters' colony where clay idols of Durga are sculpted), Prinsep Ghat for scenic Hooghly riverbank sunsets and wooden boat rides, St. Paul's Cathedral, Marble Palace, and South Park Street Cemetery.",
            AverageBudgetPerDay = "Kolkata is widely considered the most affordable metropolitan city in India. Budget travelers can easily manage on 1,200-2,200 INR (15-27 USD) per day with budget stays, street food, and metro/tram travel. Mid-range travelers spending 3,500-6,000 INR (42-75 USD) per day can stay in comfortable hotels, dine at historic Park Street restaurants, and hire taxis for all tours. Luxury heritage hotels like The Oberoi Grand or ITC Royal Bengal cost 10,000-20,000+ INR per night. Kolkata Metro tokens start at just 5 INR, and Yellow Taxis/Uber/trams are very budget-friendly.",
            LocalCuisine = "Kolkata is a foodie's paradise. Must-try items include: Kolkata Biryani (fragrant Awadhi-style biryani with succulent mutton/chicken, signature spiced potato, and boiled egg — try Arsalan, Shiraz, or Aminia), Kathi Rolls (invented at Nizam's in New Market — paratha wrapped around spiced chicken/mutton/egg kebabs), Bengali Fish Curry & Rice (Macher Jhol with Rui/Katla, and seasonal Hilsa/Ilish in mustard gravy at 6 Ballygunge Place, Kasturi, or Oh! Calcutta), Puchka (Kolkata's tangy, spicy version of pani puri made with mashed potatoes and tamarind water), Chelo Kebab at Peter Cat on Park Street, Luchi with Cholar Dal or Kosha Mangsho (slow-cooked mutton curry) at Golbari in Shyambazar, Telebhaja (crispy fritters), and iconic sweets: warm baked Rosogolla, Mishti Doi (sweet fermented yogurt), Sandesh from Balaram Mullick or KC Das, and Darjeeling tea at Flurys heritage tearoom.",
            TravelTips = "Experience the historic Kolkata Tram — the oldest operating electric tram system in Asia (ticket under 10 INR). Use the Kolkata Metro (India's first metro system) for fast travel and to avoid traffic jams. Take an early morning walk or an evening country boat (nouka) ride from Prinsep Ghat overlooking the Vidyasagar Setu. If visiting during Durga Puja (usually September-October), plan pandal-hopping itineraries in advance as millions take to the streets overnight. Yellow ambassador taxis are iconic but often require meter negotiation; Ola/Uber/Metro are reliable alternatives. Don't miss stopping for an adda (leisurely conversation) over cup of infused black coffee at Indian Coffee House on College Street."
        }
    ];
